def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        m, n, t = map(int, input_data.split())
    except ValueError:
        return

    # Define the complexity functions based on the problem statement
    # t=1: n!
    # t=2: 2^n
    # t=3: n^4
    # t=4: n^3
    # t=5: n^2
    # t=6: n * log2(n)
    # t=7: n

    def get_operations(n, t):
        if t == 1:
            # n!
            # Since n can be up to 10^9, we cannot compute factorial directly.
            # However, n! exceeds 10^9 for n >= 13.
            # We can check small n directly and return infinity (or > m) for larger n.
            if n > 20:
                return float('inf')
            res = 1
            for i in range(1, n + 1):
                res *= i
                if res > m:
                    return res + 1 # Early exit if already exceeds m
            return res

        elif t == 2:
            # 2^n
            # 2^n exceeds 10^9 when n >= 30 (2^30 approx 1.07e9)
            if n > 30:
                return float('inf')
            res = 1 << n
            return res + 1 if res > m else res

        elif t == 3:
            # n^4
            # Need to be careful with overflow if we just compute directly, 
            # though Python handles large integers automatically.
            # We can check if n is too large before computing.
            # n^4 <= 10^9 implies n <= 56 (56^4 = 9834496, 57^4 > 10^9)
            if n > 60:
                return float('inf')
            return n**4

        elif t == 4:
            # n^3
            # n^3 <= 10^9 implies n <= 1000 (1000^3 = 10^9)
            if n > 10000:
                return float('inf')
            return n**3

        elif t == 5:
            # n^2
            # n^2 <= 10^9 implies n <= 31622 (31622^2 approx 10^9)
            if n > 100000:
                return float('inf')
            return n**2

        elif t == 6:
            # n * log2(n)
            # log2(n) grows slowly. Even for n=10^9, log2(n) is approx 30.
            # 10^9 * 30 = 3e10 > 10^9. So for large n it will TLE.
            # Let's compute directly, but be mindful of very large numbers if n is huge.
            # If n is very large (e.g., 10^9), result is ~3e10 which is > 10^9.
            # We can check threshold: n * log2(n) <= 10^9.
            # Approximate: n <= 10^9 / log2(10^9) = 10^9 / 30 = 33,333,333.
            # So if n > 40,000,000 it's likely TLE.
            if n > 50000000:
                return float('inf')
            import math
            return int(n * (math.log2(n)))

        elif t == 7:
            # n
            if n > m:
                return float('inf')
            return n

    ops = get_operations(n, t)

    if ops <= m:
        print("AC")
    else:
        print("TLE")

